def _load_prior_fence_proof() -> dict[str, Any]:
    raw = zlib.decompress(base64.b64decode("".join(_PRIOR_FENCE_PROOF_ZLIB_BASE64)))
    proof = json.loads(raw.decode("utf-8"))
    canonical_raw = json.dumps(
        proof,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if hashlib.sha256(canonical_raw).hexdigest() != PRIOR_FENCE_PROOF_CANONICAL_SHA256:
        raise ValueError("C23 prior-fence proof digest differs")
    if len(canonical_raw) != PRIOR_FENCE_PROOF_CANONICAL_RAW_BYTES:
        raise ValueError("C23 prior-fence proof byte count differs")
    return proof


