def assert_corpus() -> None:
    if len(EXISTING_PATHS) != 105 or len(NEW_PATHS) != 14 or len(PATH_FENCE) != 119:
        raise ValueError("C23 path fence must be exactly 119=105+14")
    if len(set(PATH_FENCE)) != len(PATH_FENCE):
        raise ValueError("C23 path fence contains duplicates")
    if CORPUS["requiredContractNames"] != list(CONTRACT_NAMES):
        raise ValueError("C23 contract family set differs")
    if CORPUS["persistentSchemaVersion"] != 22 or CORPUS["recordsSchemaVersion"] != 21:
        raise ValueError("C23 persistence versions differ")
    if CORPUS["persistentKindLifecycleModelCount"] != 84 or CORPUS["durableFamilyCount"] != 2:
        raise ValueError("C23 model/family counts differ")
    if CORPUS["persistence"]["persistedFamilies"] != ["FieldReferenceReleaseV1", "FieldReferenceBindingV1"]:
        raise ValueError("C23 durable family set differs")
    if CORPUS["persistence"]["nonPersistentFamilies"] != ["FieldReferencePackStagingV1", "FieldReferenceOfflineReadinessV1"]:
        raise ValueError("C23 nonpersistent family set differs")
    if CORPUS["persistence"]["secondStore"] or CORPUS["persistence"]["secondWriter"]:
        raise ValueError("C23 second store/writer is prohibited")
    if (
        PRIOR_FENCE_PROOF.get("fenceCount") != 60
        or PRIOR_FENCE_PROOF.get("priorOwnedPathCount") != PRIOR_FENCE_PRIOR_OWNED_PATH_COUNT
        or PRIOR_FENCE_PROOF.get("overlapCount") != PRIOR_FENCE_OVERLAP_COUNT
        or PRIOR_FENCE_PROOF.get("authorizedOverlapCount") != PRIOR_FENCE_OVERLAP_COUNT
        or PRIOR_FENCE_PROOF.get("unauthorizedOverlapCount") != 0
        or len(PRIOR_FENCE_OVERLAPS) != PRIOR_FENCE_OVERLAP_COUNT
        or PRIOR_FENCE_PROOF.get("authorizedOverlapEdges") != list(PRIOR_FENCE_OVERLAPS)
    ):
        raise ValueError("C23 prior-fence proof differs")


assert_corpus()
